using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    while (n--) {
        string r;
        cin >> r;

        int remainder = 0;
        for (char c : r) {
            if (isdigit(static_cast<unsigned char>(c))) {
                remainder = (remainder + (c - '0')) % 3;
            }
        }

        cout << (remainder == 0 ? "YES" : "NO") << '\n';
    }

    return 0;
}

